package com.finguard.service;
import com.finguard.entity.*; import com.finguard.repository.*; import com.finguard.risk.RiskEvaluationService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class TransactionService { private final AccountRepository accounts; private final TransactionRepository transactions; private final RiskEvaluationService risk; public TransactionService(AccountRepository a,TransactionRepository t,RiskEvaluationService r){accounts=a;transactions=t;risk=r;}
@Transactional public Transaction deposit(UUID userId,BigDecimal amount){if(amount.signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero"); Account a=accounts.findByUserId(userId).orElseThrow(); a=accounts.findByIdForUpdate(a.getId()).orElseThrow();a.setBalance(a.getBalance().add(amount));return save(a.getUser(),a,null,TransactionType.DEPOSIT,amount);}
@Transactional public Transaction withdraw(UUID userId,BigDecimal amount){if(amount.signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero");Account a=accounts.findByUserId(userId).orElseThrow();a=accounts.findByIdForUpdate(a.getId()).orElseThrow();if(a.getBalance().compareTo(amount)<0)throw new IllegalArgumentException("Insufficient account balance");a.setBalance(a.getBalance().subtract(amount));return save(a.getUser(),a,null,TransactionType.WITHDRAWAL,amount);}
private Transaction save(User user,Account source,Account destination,TransactionType type,BigDecimal amount){Transaction t=new Transaction();t.setUser(user);t.setSourceAccount(source);t.setDestinationAccount(destination);t.setType(type);t.setAmount(amount);t.setStatus(TransactionStatus.COMPLETED);t.setTransactionReference("FG-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());return transactions.save(t);}}
